import{_ as a,c as s,o as t,ag as i}from"./chunks/framework.B-XtCDNB.js";const h=JSON.parse('{"title":"Genie sample code","description":"Genie sample code These pages host the Genie examples that were listed on the GNOME Wiki under Projects/Genie/Examples. The original wiki is retired; the sources here are taken from the wiki archive...","frontmatter":{},"headers":[],"relativePath":"genie/sample-code/index.md","filePath":"genie/sample-code/index.md","lastUpdated":1779042615000}'),l={name:"genie/sample-code/index.md"};function r(o,e,n,c,d,m){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="genie-sample-code" tabindex="-1">Genie sample code <a class="header-anchor" href="#genie-sample-code" aria-label="Permalink to &quot;Genie sample code&quot;">​</a></h1><p>These pages host the Genie examples that were listed on the GNOME Wiki under <a href="https://wiki.gnome.org/Projects/Genie/Examples" target="_blank" rel="noreferrer">Projects/Genie/Examples</a>. The original wiki is retired; the sources here are taken from the wiki archive and adapted only where noted (for example clearer tree walks or compile filenames). Each page is self-contained: you can copy a fenced block into a <code>.gs</code> file and compile it. <strong>Genie requires tab characters for indentation</strong>; the fenced sources here use tabs so they work with <code>valac</code> after copy-paste.</p><div class="warning custom-block"><p class="custom-block-title">Legacy APIs</p><p>Several samples target <strong>GTK+ 2</strong>, <strong>GTK+ 3</strong>, <strong>libsoup 2.4</strong>, or older <code>pkg-config</code> names. They are useful for learning Genie syntax and patterns, but expect to adjust packages and APIs for a current desktop or distribution.</p></div><h2 id="samples" tabindex="-1">Samples <a class="header-anchor" href="#samples" aria-label="Permalink to &quot;Samples&quot;">​</a></h2><ul><li><a href="./basic-samples.html">Basic samples</a> — hello world, I/O, math, arguments, files, processes, minimal GObject class.</li><li><a href="./advanced-sample.html">Advanced sample</a> — custom <code>event</code> and a number-guessing game.</li><li><a href="./cairo-sample.html">Cairo sample</a> — GTK drawing with Cairo, plus a GTK+ 2 shaped clock window.</li><li><a href="./curses-sample.html">Curses sample</a> — minimal ncurses program.</li><li><a href="./gio-networking-sample.html">GIO networking sample</a> — small threaded TCP HTTP server.</li><li><a href="./libsoup-sample.html">LibSoup sample</a> — tiny <code>Soup.Server</code> with HTML and XML routes.</li><li><a href="./xml-sample.html">XML sample (libxml2)</a> — parse, build in memory, and <code>Xml.TextWriter</code> output.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../introduction.html">Introduction to Genie</a> — tutorial in this documentation.</li><li><a href="./../resources.html">Tutorials, Blogs and Code Examples</a> — more external links.</li><li><a href="/sample-code/">Vala sample code</a> — many related patterns in Vala syntax.</li></ul>',7)])])}const u=a(l,[["render",r]]);export{h as __pageData,u as default};
